using namespace std;

class Solution {
public:
    int minSubarrayLen(vector<int>& nums, int k) {
        unordered_map<int, int> counts;
        long long cur_sum = 0;
        int left = 0;
        int min_len = INT_MAX;
        for (int right = 0; right < (int)nums.size(); right++) {
            int x = nums[right];
            if (counts[x] == 0) cur_sum += x;
            counts[x]++;
            while (cur_sum >= k && left <= right) {
                min_len = min(min_len, right - left + 1);
                int out = nums[left];
                counts[out]--;
                if (counts[out] == 0) cur_sum -= out;
                left++;
            }
        }
        return min_len == INT_MAX ? -1 : min_len;
    }
};

import java.util.*;

class Solution {
    public int minSubarrayLen(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        long curSum = 0;
        int left = 0;
        int minLen = Integer.MAX_VALUE;
        for (int right = 0; right < nums.length; right++) {
            int x = nums[right];
            if (counts.getOrDefault(x, 0) == 0) curSum += x;
            counts.put(x, counts.getOrDefault(x, 0) + 1);
            while (curSum >= k && left <= right) {
                minLen = Math.min(minLen, right - left + 1);
                int out = nums[left];
                int c = counts.get(out) - 1;
                if (c == 0) {
                    counts.remove(out);
                    curSum -= out;
                } else {
                    counts.put(out, c);
                }
                left++;
            }
        }
        return minLen == Integer.MAX_VALUE ? -1 : minLen;
    }
}

var minSubarrayLen = function(nums, k) {
    const counts = new Map();
    let curSum = 0;
    let left = 0;
    let minLen = Infinity;
    for (let right = 0; right < nums.length; right++) {
        const x = nums[right];
        if (!counts.has(x) || counts.get(x) === 0) curSum += x;
        counts.set(x, (counts.get(x) || 0) + 1);
        while (curSum >= k && left <= right) {
            minLen = Math.min(minLen, right - left + 1);
            const out = nums[left];
            const c = counts.get(out) - 1;
            if (c === 0) {
                counts.delete(out);
                curSum -= out;
            } else {
                counts.set(out, c);
            }
            left++;
        }
    }
    return minLen === Infinity ? -1 : minLen;
};
